using Avalonia.Controls;
using Avalonia.Media.Imaging;
using Avalonia.Platform;

namespace Hider
{
    /// <summary>The mosaic icon (FR-71), generated by scripts/make_icons.py into Assets/.</summary>
    public static class AppIcons
    {
        private static Bitmap? image;

        /// <summary>32 px bitmap for in-window use (the delete confirmation).</summary>
        public static Bitmap Image => image ??= Load("hider-32.png");

        /// <summary>
        /// Tray and window icon: the multi-size .ico on Windows (the shell picks 16 / 20 / 24 / 32 by DPI), a 48 px PNG
        /// elsewhere (the StatusNotifierItem host scales it).
        /// </summary>
        public static WindowIcon CreateWindowIcon()
        {
            using var stream = AssetLoader.Open(Uri(OperatingSystem.IsWindows() ? "hider.ico" : "hider-48.png"));
            return new WindowIcon(stream);
        }

        private static Bitmap Load(string _name)
        {
            using var stream = AssetLoader.Open(Uri(_name));
            return new Bitmap(stream);
        }

        private static Uri Uri(string _name)
        {
            return new Uri($"avares://Hider/Assets/{_name}");
        }
    }
}
